<section class="gamification-list"><header><h1><?php echo $this->lang('Matches') ?></h1></header><div class="gamification-fixtures"><?php foreach ($matches as $match): ?><article class="gamification-match"><time><?php echo utf8_htmlentities($match['starts_at'] ?? '') ?></time><a href="<?php echo url('matches/'.$match['match_id'].'/'.url_title($match['title'])) ?>"><strong><?php echo utf8_htmlentities($match['home_team_title'] ?: $match['home_name']) ?></strong><span><?php echo $match['score_home'] === NULL ? $this->lang('VS') : (int)$match['score_home'].' - '.(int)$match['score_away'] ?></span><strong><?php echo utf8_htmlentities($match['away_team_title'] ?: $match['away_name']) ?></strong></a></article><?php endforeach ?></div></section>
